<script setup>
import { ref, computed, shallowRef, watch, nextTick, onBeforeUnmount } from 'vue'
import ExcelJS from 'exceljs'
import Chart from 'chart.js/auto'
import { PDFDocument } from 'pdf-lib'
import { getDocument, GlobalWorkerOptions } from 'pdfjs-dist'
import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url'
GlobalWorkerOptions.workerSrc = workerUrl
const book=shallowRef(null), sheetId=ref(''), filename=ref(''), busy=ref(false), error=ref(''), result=shallowRef(null), canvas=ref(null)
const idCol=ref(0), nameCol=ref(0), scoreCol=ref(0), groupCol=ref(0), keep=ref('last'), stage=ref(0)
let chart=null
const sheet=computed(()=>book.value?.getWorksheet(Number(sheetId.value)))
const headers=computed(()=>Array.from({length:Math.min(sheet.value?.columnCount||0,100)},(_,i)=>({id:i+1,name:sheet.value.getRow(1).getCell(i+1).text.trim()||`欄 ${i+1}`})))
const steps=['讀取資料','清理及去重','計算統計','建立圖表','產生報告']
function clear(){result.value=null;stage.value=0;chart?.destroy();chart=null}
function choose(){clear();const h=headers.value;const find=(r)=>h.find(x=>r.test(x.name))?.id||0;idCol.value=find(/學號|student.?id/i);nameCol.value=find(/姓名|name/i);scoreCol.value=find(/成績|分數|score/i);groupCol.value=find(/班級|class/i)}
watch(sheetId,choose)
watch([idCol,nameCol,scoreCol,groupCol,keep],clear)
function text(cell){return cell.text.trim()}
async function upload(e){const f=e.target.files?.[0];e.target.value='';if(!f)return;busy.value=true;error.value='';clear();book.value=null;try{if(!/\.xlsx$/i.test(f.name)||f.size>10*1024*1024)throw Error('請選擇 10 MB 以內的 XLSX 檔案');const b=new ExcelJS.Workbook();await b.xlsx.load(await f.arrayBuffer());if(!b.worksheets.length)throw Error('找不到工作表');book.value=b;filename.value=f.name;sheetId.value=String(b.worksheets[0].id);choose()}catch(e){error.value=e.message+(String(e.message).includes('sheets')?'；請用 Excel 另存新檔後再試。':'')}finally{busy.value=false}}
async function example(){clear();error.value='';const b=new ExcelJS.Workbook(),s=b.addWorksheet('學生成績');s.addRows([['學號','姓名','班級','成績'],['S001',' 王 小明 ','資管一甲',85],['S002','陳小華','資管一甲',90],['S001','王小明','資管一甲',92],['S003','李小美','資管二甲',88],['S004','張小文','資管二甲',96],['S005','林小安','資管二甲',''],['S006','黃小美','資管一甲',105]]);book.value=b;filename.value='內建模擬成績.xlsx';sheetId.value=String(s.id);choose()}
function score(cell){let v=cell.value;if(v&&typeof v==='object')v=v.result;if(typeof v==='string'&&v.trim()&&/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(v.trim()))v=Number(v);return typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=100?v:null}
function stat(rows){const a=rows.map(r=>r.score),sum=a.reduce((s,v)=>s+v,0);return {n:a.length,sum,avg:a.length?sum/a.length:null,min:a.length?Math.min(...a):null,max:a.length?Math.max(...a):null}}
const fmt=v=>v==null?'—':Number(v.toFixed(2)).toString()
async function run(){clear();error.value='';busy.value=true;try{const s=sheet.value;if(!s||!idCol.value||!scoreCol.value)throw Error('請選擇學號及成績欄位');const cols=[idCol.value,scoreCol.value,nameCol.value,groupCol.value].filter(Boolean);if(new Set(cols).size!==cols.length)throw Error('各欄位不得重複選擇');if(s.rowCount>20001||s.columnCount>100)throw Error('最多支援 20,000 筆資料、100 欄');stage.value=1;let original=0;const valid=[],excluded=[];s.eachRow((r,i)=>{if(i===1)return;original++;const id=text(r.getCell(idCol.value)),n=score(r.getCell(scoreCol.value));if(!id||n===null){excluded.push({row:i,id,reason:!id?'學號空白':'成績缺漏或不在 0–100 分'});return}valid.push({row:i,id,name:nameCol.value?text(r.getCell(nameCol.value)).replace(/\s+/g,''):'',group:groupCol.value?text(r.getCell(groupCol.value))||'未分類':'全體',score:n})});const map=new Map();for(const r of valid){if(map.has(r.id)){const old=map.get(r.id);if(keep.value==='last'){excluded.push({...old,reason:'重複學號（保留最後有效筆）'});map.set(r.id,r)}else excluded.push({...r,reason:'重複學號（保留第一有效筆）'})}else map.set(r.id,r)}const rows=[...map.values()].sort((a,b)=>a.row-b.row);stage.value=2;const overall=stat(rows),groups=new Map();for(const r of rows){if(!groups.has(r.group))groups.set(r.group,[]);groups.get(r.group).push(r)}const grouped=[...groups].map(([name,rs])=>({name,...stat(rs)}));stage.value=3;result.value={original,rows,excluded,overall,grouped};await nextTick();if(canvas.value&&grouped.length){chart=new Chart(canvas.value,{type:'bar',data:{labels:grouped.slice(0,100).map(g=>g.name),datasets:[{label:'平均成績',data:grouped.slice(0,100).map(g=>g.avg),backgroundColor:'#14b8a6'}]},options:{responsive:true,maintainAspectRatio:false,animation:false,scales:{y:{min:0,max:100}},plugins:{legend:{display:false}}}})}stage.value=4;await nextTick();stage.value=5}catch(e){error.value=e.message;clear()}finally{busy.value=false}}
const report=computed(()=>{const r=result.value;if(!r)return '';return `# 學生成績分析報告\n\n來源：${filename.value}\n\n原始 ${r.original} 筆；保留 ${r.rows.length} 筆；排除 ${r.excluded.length} 筆。\n\n平均：${fmt(r.overall.avg)}；最低：${fmt(r.overall.min)}；最高：${fmt(r.overall.max)}。\n\n${r.grouped.map(g=>`- ${g.name}：${g.n} 人，平均 ${fmt(g.avg)} 分`).join('\n')}\n\n限制：僅統計有效成績；同學號依指定規則去重；未推論成績變動原因。`})
function save(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function downloadReport(){save(new Blob([report.value],{type:'text/markdown;charset=utf-8'}),'成績分析報告.md')}
function downloadChart(){if(!canvas.value)return;const c=document.createElement('canvas');c.width=canvas.value.width;c.height=canvas.value.height;const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(canvas.value,0,0);c.toBlob(b=>{if(b)save(b,'班級平均成績.png')})}
async function downloadExcel(){const r=result.value;if(!r)return;busy.value=true;try{const b=new ExcelJS.Workbook();for(const [name,rows] of [['清理後資料',[['原始列','學號','姓名','班級','成績'],...r.rows.map(x=>[x.row,x.id,x.name,x.group,x.score])]],['統計報表',[['分類','人數','加總','平均','最低','最高'],['全體',r.overall.n,r.overall.sum,r.overall.avg,r.overall.min,r.overall.max],...r.grouped.map(g=>[g.name,g.n,g.sum,g.avg,g.min,g.max])]],['排除紀錄',[['原始列','學號','原因'],...r.excluded.map(x=>[x.row,x.id,x.reason])]]]){const s=b.addWorksheet(name);s.addRows(rows);s.getRow(1).font={bold:true};s.columns.forEach(c=>c.width=24)}save(new Blob([await b.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'成績分析成果.xlsx')}catch(e){error.value=e.message}finally{busy.value=false}}
onBeforeUnmount(()=>chart?.destroy())
const mode=ref('student'), revBusy=ref(false), revError=ref(''), revBook=shallowRef(null), revSheet=ref(''), revFile=ref(''), revResult=shallowRef(null)
const monthCol=ref(0), deptCol=ref(0), incomeCol=ref(0), costCol=ref(0)
const trendCanvas=ref(null), deptCanvas=ref(null), costCanvas=ref(null)
let revCharts=[]
const revWorksheet=computed(()=>revBook.value?.getWorksheet(Number(revSheet.value)))
const revHeaders=computed(()=>Array.from({length:Math.min(revWorksheet.value?.columnCount||0,100)},(_,i)=>({id:i+1,name:revWorksheet.value.getRow(1).getCell(i+1).text.trim()||`欄 ${i+1}`})))
function revClear(){revCharts.forEach(c=>c.destroy());revCharts=[];revResult.value=null}
function switchMode(v){if(busy.value||revBusy.value||pdfBusy.value)return;clear();revClear();mode.value=v}
function revChoose(){revClear();const find=r=>revHeaders.value.find(h=>r.test(h.name))?.id||0;monthCol.value=find(/月份|日期|month|date/i);deptCol.value=find(/部門|department|dept/i);incomeCol.value=find(/營收|收入|revenue|income/i);costCol.value=find(/成本|cost/i)}
watch(revSheet,revChoose)
watch([monthCol,deptCol,incomeCol,costCol],revClear)
function parseCsv(input){const rows=[];let row=[],field='',quoted=false,closed=false;input=input.replace(/^\uFEFF/,'');for(let i=0;i<input.length;i++){const c=input[i];if(quoted){if(c==='"'){if(input[i+1]==='"'){field+='"';i++}else{quoted=false;closed=true}}else field+=c;continue}if(c==='"'&&!field&&!closed){quoted=true;continue}if(c===','||c==='\n'||c==='\r'){row.push(field);field='';closed=false;if(c!==','){if(c==='\r'&&input[i+1]==='\n')i++;rows.push(row);row=[]}continue}if(closed||c==='"')throw Error('CSV 引號格式錯誤');field+=c}if(quoted)throw Error('CSV 引號未閉合');if(field||row.length||closed){row.push(field);rows.push(row)}return rows}
function revLoad(b,name){if(!b.worksheets.length)throw Error('找不到工作表');revBook.value=b;revFile.value=name;revSheet.value=String(b.worksheets[0].id);revChoose()}
async function revUpload(e){const f=e.target.files?.[0];e.target.value='';if(!f)return;revBusy.value=true;revError.value='';revClear();revBook.value=null;try{if(f.size>10*1024*1024)throw Error('檔案上限 10 MB');const b=new ExcelJS.Workbook();if(/\.xlsx$/i.test(f.name)){await b.xlsx.load(await f.arrayBuffer())}else if(/\.csv$/i.test(f.name)){const rows=parseCsv(await f.text());if(rows.length>20001||rows.some(r=>r.length>100))throw Error('最多 20,000 筆、100 欄');b.addWorksheet('CSV').addRows(rows)}else throw Error('請選擇 XLSX 或 UTF-8 CSV');revLoad(b,f.name)}catch(e){revError.value=e.message+(String(e.message).includes('sheets')?'；請另存 XLSX 或改用 CSV。':'')}finally{revBusy.value=false}}
const revDemo=[['月份','部門','營收','成本'],['2026-01','業務部',350000,250000],['2026-02','資訊部',400000,280000],['2026-03','業務部',450000,300000],['2026-04','服務部',500000,320000],['2026-05','資訊部',550000,340000],['2026-06','服務部',600000,360000],['2026-06','業務部','',10000]]
function revExample(){revError.value='';const b=new ExcelJS.Workbook();b.addWorksheet('企業營收').addRows(revDemo);revLoad(b,'內建模擬營收')}
function amount(cell){let v=cell.value;if(v&&typeof v==='object')v=v.result;if(typeof v==='string'){v=v.trim();if(!/^[+-]?(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?$/.test(v))return null;v=Number(v.replace(/,/g,''))}return typeof v==='number'&&Number.isFinite(v)&&v>=0?v:null}
function monthKey(cell){const v=cell.value;if(v instanceof Date&&!isNaN(v))return v.toISOString().slice(0,7);const t=cell.text.trim();const m=t.match(/^(\d{4})[-/年](\d{1,2})(?:月|[-/]\d{1,2})?$/);if(m&&+m[2]>=1&&+m[2]<=12)return `${m[1]}-${m[2].padStart(2,'0')}`;const n=t.match(/^(\d{1,2})月?$/);return n&&+n[1]>=1&&+n[1]<=12?`月份-${n[1].padStart(2,'0')}`:null}
function revStat(rows){const income=rows.reduce((s,r)=>s+r.income,0),cost=rows.reduce((s,r)=>s+r.cost,0),profit=income-cost;return {n:rows.length,income,cost,profit,margin:income?profit/income*100:null}}
function revGroup(rows,key){const map=new Map();for(const r of rows){if(!map.has(r[key]))map.set(r[key],[]);map.get(r[key]).push(r)}return [...map].map(([name,rs])=>({name,...revStat(rs)}))}
const money=v=>v==null?'—':v.toLocaleString('zh-TW',{maximumFractionDigits:2})
async function revRun(){revClear();revError.value='';revBusy.value=true;try{const s=revWorksheet.value,cols=[monthCol.value,deptCol.value,incomeCol.value,costCol.value];if(!s||cols.some(c=>!c)||new Set(cols).size!==4)throw Error('請選擇四個不同欄位');if(s.rowCount>20001||s.columnCount>100)throw Error('最多 20,000 筆、100 欄');const rows=[],excluded=[];s.eachRow((r,i)=>{if(i===1)return;const month=monthKey(r.getCell(cols[0])),dept=text(r.getCell(cols[1])),income=amount(r.getCell(cols[2])),cost=amount(r.getCell(cols[3]));const reason=[!month?'月份無效':'',!dept?'部門空白':'',income===null?'營收缺漏或無效':'',cost===null?'成本缺漏或無效':''].filter(Boolean).join('；');if(reason)excluded.push({row:i,reason});else rows.push({row:i,month,dept,income,cost,profit:income-cost})});if(!rows.length)throw Error('沒有有效資料，請檢查欄位及格式');if(new Set(rows.map(r=>r.month.startsWith('月份-'))).size>1)throw Error('月份不可混用有年份與無年份格式');const overall=revStat(rows),months=revGroup(rows,'month').sort((a,b)=>a.name.localeCompare(b.name)),depts=revGroup(rows,'dept').sort((a,b)=>b.income-a.income);revResult.value={rows,excluded,overall,months,depts};await nextTick();const options={responsive:true,maintainAspectRatio:false,animation:false};const ms=months.slice(0,100),ds=depts.slice(0,100);revCharts.push(new Chart(trendCanvas.value,{type:'line',data:{labels:ms.map(x=>x.name),datasets:[{label:'營收',data:ms.map(x=>x.income),borderColor:'#2563eb'},{label:'成本',data:ms.map(x=>x.cost),borderColor:'#ea580c'}]},options}));revCharts.push(new Chart(deptCanvas.value,{type:'bar',data:{labels:ds.map(x=>x.name),datasets:[{label:'營收',data:ds.map(x=>x.income),backgroundColor:'#14b8a6'}]},options}));if(overall.cost>0){const cs=depts.slice(0,99),other=depts.slice(99).reduce((s,x)=>s+x.cost,0);revCharts.push(new Chart(costCanvas.value,{type:'doughnut',data:{labels:[...cs.map(x=>x.name),...(depts.length>99?['其餘部門']:[])],datasets:[{data:[...cs.map(x=>x.cost),...(depts.length>99?[other]:[])],backgroundColor:Array.from({length:100},(_,i)=>`hsl(${i*137.5%360},65%,55%)`)}]},options}))}}catch(e){revError.value=e.message;revClear()}finally{revBusy.value=false}}
const revReport=computed(()=>{const r=revResult.value;if(!r)return '';const o=r.overall;return `# 企業營收分析報告\n\n來源：${revFile.value}\n\n有效 ${r.rows.length} 筆；排除 ${r.excluded.length} 筆。\n\n營收：${money(o.income)}；成本：${money(o.cost)}；毛利：${money(o.profit)}；整體毛利率：${money(o.margin)}${o.margin===null?'':'%'}。\n\n## 部門分析\n${r.depts.map(d=>`- ${d.name}：營收 ${money(d.income)}，毛利 ${money(d.profit)}`).join('\n')}\n\n## 限制\n成本視為銷貨或服務成本；不代表淨利。負值、無效月份及缺漏資料排除；不自動去重。幣別沿用來源資料且須一致。`})
function revPng(canvas,name){if(!canvas)return;const c=document.createElement('canvas');c.width=canvas.width;c.height=canvas.height;const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(canvas,0,0);c.toBlob(b=>{if(b)save(b,name)})}
async function revExcel(){const r=revResult.value;if(!r)return;revBusy.value=true;try{const b=new ExcelJS.Workbook();const head=['分類','筆數','營收','成本','毛利','毛利率(%)'];const line=(n,x)=>[n,x.n,x.income,x.cost,x.profit,x.margin];for(const [n,rs] of [['清理資料',[['原始列','月份','部門','營收','成本','毛利'],...r.rows.map(x=>[x.row,x.month,x.dept,x.income,x.cost,x.profit])]],['整體統計',[head,line('全體',r.overall)]],['月份統計',[head,...r.months.map(x=>line(x.name,x))]],['部門統計',[head,...r.depts.map(x=>line(x.name,x))]],['排除紀錄',[['原始列','原因'],...r.excluded.map(x=>[x.row,x.reason])]]]){const s=b.addWorksheet(n);s.addRows(rs);s.getRow(1).font={bold:true};s.columns.forEach(c=>c.width=24)}save(new Blob([await b.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'企業營收分析.xlsx')}catch(e){revError.value=e.message}finally{revBusy.value=false}}
onBeforeUnmount(revClear)

const pdfFiles=shallowRef([]), pdfBusy=ref(false), pdfError=ref(''), pdfResult=shallowRef(null), pdfStage=ref('')
let pdfDisposed=false
function pdfAdd(e){const files=Array.from(e.target.files||[]);e.target.value='';pdfError.value='';if(files.some(f=>! /\.pdf$/i.test(f.name))){pdfError.value='僅接受 PDF 檔案';return}const next=[...pdfFiles.value,...files];if(next.length>20||next.reduce((n,f)=>n+f.size,0)>50*1024*1024){pdfError.value='最多 20 份 PDF，合計 50 MB';return}pdfFiles.value=next;pdfResult.value=null}
function pdfMove(i,d){const next=[...pdfFiles.value];if(i+d<0||i+d>=next.length)return;[next[i],next[i+d]]=[next[i+d],next[i]];pdfFiles.value=next;pdfResult.value=null}
function pdfRemove(i){pdfFiles.value=pdfFiles.value.filter((_,j)=>i!==j);pdfResult.value=null}
async function pdfRun(){pdfBusy.value=true;pdfError.value='';pdfResult.value=null;try{const merged=await PDFDocument.create(), pages=[], sources=[];for(const f of pdfFiles.value){if(pdfDisposed)return;pdfStage.value='讀取 '+f.name;const bytes=new Uint8Array(await f.arrayBuffer());const src=await PDFDocument.load(bytes);if(merged.getPageCount()+src.getPageCount()>300)throw Error('合計最多 300 頁');const task=getDocument({data:bytes.slice()});try{const doc=await task.promise;const start=pages.length+1;for(let i=1;i<=doc.numPages;i++){if(pdfDisposed)return;pdfStage.value=`擷取 ${f.name}：${i}/${doc.numPages}`;const page=await doc.getPage(i);const content=await page.getTextContent();const text=content.items.map(x=>typeof x.str==='string'?x.str+(x.hasEOL?'\n':' '):'').join('').trim();pages.push({number:pages.length+1,file:f.name,local:i,text});page.cleanup()}const copied=await merged.copyPages(src,src.getPageIndices());copied.forEach(p=>merged.addPage(p));sources.push({name:f.name,start,end:pages.length})}finally{await task.destroy()}}if(pdfDisposed)return;pdfStage.value='產生合併檔與整理報告';const text=pages.map(p=>`--- 第 ${p.number} 頁（${p.file} / ${p.local}）---\n${p.text||'[無可擷取文字]'}`).join('\n\n');const sentences=pages.flatMap(p=>p.text.split(/(?<=[。！？!?])|\n+/u).map(x=>x.trim()).filter(x=>x.length>=12).map(x=>({x,page:p.number})));const terms=new Map();const words=x=>Array.from(x.toLowerCase().matchAll(/[\p{Script=Han}]{2,}|[a-z0-9]{3,}/gu),m=>m[0]).flatMap(w=>/\p{Script=Han}/u.test(w)?Array.from({length:Math.max(1,w.length-1)},(_,i)=>w.slice(i,i+2)):[w]);for(const t of sentences)for(const w of new Set(words(t.x)))terms.set(w,(terms.get(w)||0)+1);const ranked=sentences.map((t,i)=>({...t,i,score:words(t.x).reduce((n,w)=>n+(terms.get(w)||0),0)/Math.max(1,words(t.x).length)})).sort((a,b)=>b.score-a.score||a.i-b.i).slice(0,8).sort((a,b)=>a.i-b.i);const empty=pages.filter(p=>!p.text).length;const report=['# PDF 文件整理報告','',`文件 ${sources.length} 份；總頁數 ${pages.length}；無可擷取文字 ${empty} 頁。`,'','## 文件頁碼索引',...sources.map(f=>`- ${f.name}：第 ${f.start}–${f.end} 頁`),'','## 原文重點摘錄',...ranked.map(t=>`- 第 ${t.page} 頁：${t.x}`),'','限制：未執行 OCR；摘錄採詞頻評分，非生成式 AI；文字順序及版面可能與原檔不同。'].join('\n');const output=await merged.save();if(!pdfDisposed)pdfResult.value={pages,sources,text,report,output,empty};pdfStage.value='完成'}catch(e){pdfError.value='處理失敗：'+e.message;pdfStage.value=''}finally{pdfBusy.value=false}}
function pdfSave(kind){const r=pdfResult.value;if(!r)return;const [data,mime,name]=kind==='pdf'?[r.output,'application/pdf','合併文件.pdf']:kind==='txt'?[r.text,'text/plain;charset=utf-8','擷取文字.txt']:[r.report,'text/markdown;charset=utf-8','文件整理報告.md'];save(new Blob([data],{type:mime}),name)}
onBeforeUnmount(()=>{pdfDisposed=true})

</script>
<template>
<section class="orch"><div class="actions"><button :class="{primary:mode==='student'}" :disabled="busy||revBusy||pdfBusy" @click="switchMode('student')">學生成績分析</button><button :class="{primary:mode==='revenue'}" :disabled="busy||revBusy||pdfBusy" @click="switchMode('revenue')">企業營收分析</button><button :class="{primary:mode==='pdf'}" :disabled="busy||revBusy||pdfBusy" @click="switchMode('pdf')">PDF 文件整理</button></div><template v-if="mode==='student'"><header><small>SKILL ORCHESTRATOR · V7.6</small><h2>智慧技能編排中心</h2><p>學生成績分析｜一次上傳，自動完成五個處理步驟</p></header><div class="actions"><label>上傳 XLSX <input type="file" accept=".xlsx" :disabled="busy" @change="upload"></label><button :disabled="busy" @click="example">載入模擬資料</button></div><p v-if="error" role="alert" class="err">{{error}}</p><div v-if="book" class="config"><label>工作表<select v-model="sheetId" :disabled="busy"><option v-for="s in book.worksheets" :key="s.id" :value="String(s.id)">{{s.name}}</option></select></label><label v-for="item in [{label:'學號（必填）',key:'id'},{label:'姓名',key:'name'},{label:'成績（必填）',key:'score'},{label:'班級',key:'group'}]" :key="item.key">{{item.label}}<select :value="item.key==='id'?idCol:item.key==='name'?nameCol:item.key==='score'?scoreCol:groupCol" :disabled="busy" @change="e=>{const v=Number(e.target.value);if(item.key==='id')idCol=v;else if(item.key==='name')nameCol=v;else if(item.key==='score')scoreCol=v;else groupCol=v}"><option :value="0">未選擇</option><option v-for="h in headers" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>重複學號<select v-model="keep" :disabled="busy"><option value="last">保留最後有效筆</option><option value="first">保留第一有效筆</option></select></label></div><p>規則：學號去除前後空格、姓名移除空格、成績限 0–100 分；先排除無效資料，再依學號去重。原檔不變。</p><button class="primary" :disabled="busy||!sheet||!idCol||!scoreCol" @click="run">{{busy?'處理中…':'▶ 一鍵執行完整流程'}}</button><div class="pipeline"><div v-for="(s,i) in steps" :key="s" :class="{completed:stage>i}">{{stage>i?'✓':i+1}} {{s}}</div></div><template v-if="result"><div class="kpis"><div v-for="k in [['原始筆數',result.original],['保留筆數',result.rows.length],['排除筆數',result.excluded.length],['平均成績',fmt(result.overall.avg)]]" :key="k[0]"><small>{{k[0]}}</small><strong>{{k[1]}}</strong></div></div><h3>班級平均成績</h3><div class="plot"><canvas ref="canvas"></canvas></div><p v-if="result.grouped.length>100">圖表僅顯示前100組，報表包含全部。</p><h3>分類統計</h3><div class="scroll"><table><thead><tr><th>班級</th><th>人數</th><th>平均</th><th>最低</th><th>最高</th></tr></thead><tbody><tr v-for="g in result.grouped" :key="g.name"><td>{{g.name}}</td><td>{{g.n}}</td><td>{{fmt(g.avg)}}</td><td>{{fmt(g.min)}}</td><td>{{fmt(g.max)}}</td></tr></tbody></table></div><h3>排除紀錄（前20筆）</h3><p v-for="x in result.excluded.slice(0,20)" :key="x.row">第 {{x.row}} 列 · {{x.id||'空白'}} · {{x.reason}}</p><h3>自動分析報告</h3><pre>{{report}}</pre><div class="actions"><button :disabled="busy" @click="downloadExcel">下載 Excel 成果</button><button @click="downloadReport">下載 Markdown 報告</button><button :disabled="!result.grouped.length" @click="downloadChart">下載 PNG 圖表</button></div></template></template><template v-else-if="mode==='revenue'">
<header><small>SKILL ORCHESTRATOR · V7.6</small><h2>企業營收自動分析</h2><p>匯入資料 → 清理 → 統計 → 製圖 → 報告</p></header>
<div class="actions"><label>上傳 XLSX / UTF-8 CSV <input type="file" accept=".xlsx,.csv" :disabled="revBusy" @change="revUpload"></label><button :disabled="revBusy" @click="revExample">載入模擬營收</button></div>
<p v-if="revError" class="err" role="alert">{{revError}}</p>
<div v-if="revBook" class="config"><label>工作表<select v-model="revSheet" :disabled="revBusy"><option v-for="s in revBook.worksheets" :key="s.id" :value="String(s.id)">{{s.name}}</option></select></label><label>月份<select v-model.number="monthCol" :disabled="revBusy"><option :value="0">未選擇</option><option v-for="h in revHeaders" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>部門<select v-model.number="deptCol" :disabled="revBusy"><option :value="0">未選擇</option><option v-for="h in revHeaders" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>營收<select v-model.number="incomeCol" :disabled="revBusy"><option :value="0">未選擇</option><option v-for="h in revHeaders" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>成本<select v-model.number="costCol" :disabled="revBusy"><option :value="0">未選擇</option><option v-for="h in revHeaders" :key="h.id" :value="h.id">{{h.name}}</option></select></label></div>
<p>月份請用 YYYY-MM 或 1月～12月；營收、成本須為非負數且幣別一致。成本視為銷貨或服務成本。重複交易不自動刪除。</p>
<button class="primary" :disabled="revBusy||!revWorksheet||!monthCol||!deptCol||!incomeCol||!costCol" @click="revRun">{{revBusy?'處理中…':'▶ 一鍵執行企業營收分析'}}</button>
<template v-if="revResult"><div class="kpis"><div v-for="k in [['總營收',money(revResult.overall.income)],['總成本',money(revResult.overall.cost)],['毛利',money(revResult.overall.profit)],['整體毛利率',revResult.overall.margin===null?'—':money(revResult.overall.margin)+'%'],['有效筆數',revResult.rows.length],['排除筆數',revResult.excluded.length]]" :key="k[0]"><small>{{k[0]}}</small><strong>{{k[1]}}</strong></div></div>
<h3>每月營收與成本趨勢</h3><div class="plot"><canvas ref="trendCanvas"></canvas></div><button @click="revPng(trendCanvas,'營收趨勢.png')">下載趨勢 PNG</button>
<h3>各部門營收比較</h3><div class="plot"><canvas ref="deptCanvas"></canvas></div><button @click="revPng(deptCanvas,'部門營收.png')">下載部門 PNG</button>
<template v-if="revResult.overall.cost>0"><h3>各部門成本占比</h3><div class="plot"><canvas ref="costCanvas"></canvas></div><button @click="revPng(costCanvas,'部門成本.png')">下載成本 PNG</button></template><p v-if="revResult.months.length>100||revResult.depts.length>100">趨勢與部門比較圖最多顯示100組；成本圖其餘部門合併；報表包含全部。</p>
<h3>部門統計</h3><div class="scroll"><table><thead><tr><th>部門</th><th>筆數</th><th>營收</th><th>成本</th><th>毛利</th><th>毛利率</th></tr></thead><tbody><tr v-for="d in revResult.depts" :key="d.name"><td>{{d.name}}</td><td>{{d.n}}</td><td>{{money(d.income)}}</td><td>{{money(d.cost)}}</td><td>{{money(d.profit)}}</td><td>{{d.margin===null?'—':money(d.margin)+'%'}}</td></tr></tbody></table></div><h3>排除紀錄（前20筆）</h3><p v-for="x in revResult.excluded.slice(0,20)" :key="x.row">第 {{x.row}} 列 · {{x.reason}}</p><h3>自動分析報告</h3><pre>{{revReport}}</pre><div class="actions"><button :disabled="revBusy" @click="revExcel">下載 Excel 成果</button><button @click="save(new Blob([revReport],{type:'text/markdown;charset=utf-8'}),'企業營收分析.md')">下載 Markdown 報告</button></div></template>
</template>
<template v-else>
<header><small>SKILL ORCHESTRATOR · V7.6</small><h2>PDF 文件自動整理</h2><p>多份 PDF → 排序 → 合併 → 文字擷取 → 重點摘錄</p></header>
<div class="actions"><label>選擇 PDF（可多選） <input type="file" accept=".pdf,application/pdf" multiple :disabled="pdfBusy" @change="pdfAdd"></label></div>
<p>最多 20 份、50 MB、300 頁。依下列順序合併，不修改原檔。</p>
<div v-for="(f,i) in pdfFiles" :key="i" class="pdf-row"><strong>{{i+1}}. {{f.name}}</strong><span>{{(f.size/1024).toFixed(1)}} KB</span><button :disabled="pdfBusy||i===0" @click="pdfMove(i,-1)">↑</button><button :disabled="pdfBusy||i===pdfFiles.length-1" @click="pdfMove(i,1)">↓</button><button :disabled="pdfBusy" @click="pdfRemove(i)">移除</button></div>
<button class="primary" :disabled="pdfBusy||!pdfFiles.length" @click="pdfRun">{{pdfBusy?'處理中…':'▶ 一鍵整理 PDF'}}</button><p role="status">{{pdfStage}}</p><p v-if="pdfError" role="alert" class="err">{{pdfError}}</p>
<template v-if="pdfResult"><div class="kpis"><div><small>文件數</small><strong>{{pdfResult.sources.length}}</strong></div><div><small>合併頁數</small><strong>{{pdfResult.pages.length}}</strong></div><div><small>無可擷取文字</small><strong>{{pdfResult.empty}}</strong></div></div><h3>文件整理報告</h3><pre>{{pdfResult.report}}</pre><h3>擷取文字預覽（前 5000 字元）</h3><pre>{{pdfResult.text.slice(0,5000)}}</pre><div class="actions"><button @click="pdfSave('pdf')">下載合併 PDF</button><button @click="pdfSave('txt')">下載完整文字</button><button @click="pdfSave('md')">下載 Markdown 報告</button></div></template>
<p>掃描圖片未進行 OCR；加密 PDF 不支援。合併不保證保留書籤、表單互動或數位簽章。</p>
</template>
</section>
</template>
<style scoped>
.orch{color:#173b42;display:grid;gap:16px;padding:12px 0}.orch header{padding:24px;background:linear-gradient(120deg,#ccfbf1,#dbeafe);border-radius:24px}.orch h2,.orch h3,.orch p{margin:0}.orch h2{font-size:28px;font-weight:900}.orch h3{font-size:20px}.actions,.pipeline{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.config,.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px}.config label{display:grid;gap:5px;font-weight:700}.config select{padding:10px;border:1px solid #a8c7cb;border-radius:10px;background:white;color:#173b42}.orch .primary{background:#0f766e;color:white;padding:15px}.pipeline div,.kpis div{background:#edf5f5;border-radius:15px;padding:13px}.pipeline .completed{background:#ccfbf1;color:#115e59}.kpis strong{display:block;font-size:28px;color:#0f766e}.plot{height:300px;background:white;border-radius:18px;padding:12px}.scroll{overflow:auto}.orch table{width:100%;border-collapse:collapse}.orch td,.orch th{padding:9px;text-align:left;border-bottom:1px solid #dbe6e6}.orch th{background:#e1f3f1}.orch pre{white-space:pre-wrap;background:#f1f5f9;padding:16px;border-radius:14px;color:#173b42}.err{color:#b91c1c}.orch button:disabled{opacity:.5;cursor:not-allowed}
.pdf-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;background:#edf5f5;padding:12px;border-radius:12px}.pdf-row strong{flex:1;overflow-wrap:anywhere}
